def compute(vars):
    settlements = [vars["v1"], vars["v2"], vars["v3"]]
    total = sum(settlements)
    count = len(settlements)
    return {
        "value": total / count,
        "trace": {
            "settlements": settlements,
            "total": total,
            "count": count,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
